100|  <T> T postJSON(String url, Object in, TypeReference<T> out) throws IOException, InterruptedException {
101|    byte[] b = JsonCodec.toJson(in).getBytes(StandardCharsets.UTF_8);
102|    HttpRequest req = HttpRequest.newBuilder(URI.create(url))
103|        .timeout(httpTimeout)
104|        .header("Content-Type", "application/json")
105|        .POST(HttpRequest.BodyPublishers.ofByteArray(b))
106|        .build();
107|    HttpResponse<String> resp;
108|    try {
109|      resp = http.send(req, HttpResponse.BodyHandlers.ofString(StandardCharsets.UTF_8));
110|    } catch (IOException e) {
111|      // Wrap transport failures as: Post "<url>": <reason> — the URL is what makes these
112|      // diagnosable in an incident, since the cause alone rarely names the endpoint.
113|      throw new IOException("Post \"" + url + "\": " + netReason(url, e), e);
114|    }
115|    if (resp.statusCode() >= 300) {
116|      throw new JobErrorIO(sprintf("POST %s: HTTP %d: %s", url, resp.statusCode(), resp.body()));
117|    }
118|    if (out != null) {
119|      return JsonCodec.MAPPER.readValue(resp.body(), out);
120|    }
121|    return null;
122|  }
