124|  /**
125|   * A short, stable reason for the common transport failures ("connection refused",
126|   * "no such host", "i/o timeout"), naming host and port. {@code MockServicesTest} and the
127|   * incident text both depend on these strings.
128|   */
129|  static String netReason(String url, IOException e) {
130|    URI u = URI.create(url);
131|    String host = u.getHost() == null ? "" : u.getHost();
132|    int port = u.getPort() > 0 ? u.getPort() : ("https".equals(u.getScheme()) ? 443 : 80);
133|    if (Errors.find(e, java.nio.channels.UnresolvedAddressException.class) != null
134|        || Errors.find(e, java.net.UnknownHostException.class) != null) {
135|      return "dial tcp: lookup " + host + ": no such host";
136|    }
137|    if (Errors.find(e, java.net.http.HttpConnectTimeoutException.class) != null) {
138|      return "dial tcp " + host + ":" + port + ": i/o timeout";
139|    }
140|    if (Errors.find(e, java.net.http.HttpTimeoutException.class) != null) {
141|      return "context deadline exceeded (Client.Timeout exceeded while awaiting headers)";
142|    }
143|    if (Errors.find(e, java.net.ConnectException.class) != null) {
144|      return "dial tcp " + host + ":" + port + ": connect: connection refused";
145|    }
146|    return Errors.message(e);
147|  }
