200|  public Map<String, Object> issueCapitalCall(Job job) throws Exception {
201|    CapitalCallInput in = job.bind(CapitalCallInput.class);
202|    if (in.callId.isEmpty() || in.lpList == null || in.lpList.isEmpty() || in.targetAmountUSD <= 0) {
203|      throw new JobException("invalid capital call input: callId, lpList and targetAmountUSD are required");
204|    }
205|    if (in.deadlineDays <= 0) {
206|      in.deadlineDays = 10;
207|    }
208|    long spd = in.secondsPerDay;
209|    if (spd <= 0) {
210|      spd = 86400;
211|    }
212|
213|    double total = 0.0;
214|    for (LP lp : in.lpList) {
215|      total += lp.commitmentUSD;
216|    }
217|    Map<String, Object> draws = new TreeMap<>();
218|    for (LP lp : in.lpList) {
219|      double d = round2(in.targetAmountUSD * lp.commitmentUSD / total);
220|      lp.drawAmountUSD = d;
221|      draws.put(lp.lpId, d);
222|    }
223|
224|    // These go into "timestamp" columns, which carry no zone, so write the local wall clock
225|    // and read it back as UTC (see Format#rfc3339Nano).
226|    LocalDateTime now = LocalDateTime.now();
227|    LocalDateTime deadline = now.plusSeconds((long) in.deadlineDays * spd);
228|    try (Connection c = db.getConnection()) {
229|      c.setAutoCommit(false);
230|      try {
231|        try {
232|          Db.exec(c, """
233|
234|              		INSERT INTO capital_calls (call_id, fund_id, process_instance_key, target_amount_usd, status, deadline_days, seconds_per_day, deadline_date)
235|              		VALUES ($1,$2,$3,$4,'issued',$5,$6,$7)
236|              		ON CONFLICT (call_id) DO UPDATE SET process_instance_key=EXCLUDED.process_instance_key""",
237|              in.callId, in.fundId, job.processInstanceKey(), in.targetAmountUSD, in.deadlineDays, in.secondsPerDay,
238|              deadline);
239|        } catch (SQLException e) {
240|          throw new JobException("insert capital_calls: " + Errors.message(e), e);
241|        }
242|        for (LP lp : in.lpList) {
243|          try {
244|            Db.exec(c, """
245|
246|                			INSERT INTO capital_call_lps (call_id, lp_id, email, commitment_usd, draw_amount_usd, status)
247|                			VALUES ($1,$2,$3,$4,$5,'issued') ON CONFLICT (call_id, lp_id) DO NOTHING""",
248|                in.callId, lp.lpId, lp.email, lp.commitmentUSD, lp.drawAmountUSD);
249|          } catch (SQLException e) {
250|            throw new JobException("insert capital_call_lps: " + Errors.message(e), e);
251|          }
252|        }
253|        c.commit();
254|      } catch (Exception e) {
255|        c.rollback();
256|        throw e;
257|      } finally {
258|        c.setAutoCommit(true);
259|      }
260|    }
261|    event(in.callId, "", "issueCapitalCall", sprintf("Call issued for $%.0f across %d LPs (deadline %d days)",
262|        in.targetAmountUSD, in.lpList.size(), in.deadlineDays));
263|
264|    // Follow-up schedule: D+3 email, D+7 call, D+10 legal notice, then deadline.
265|    long fin = (in.deadlineDays - 10L) * spd;
266|    Map<String, Object> out = new TreeMap<>();
267|    out.put("lpList", in.lpList);
268|    out.put("drawAmounts", draws);
269|    out.put("deadlineDays", in.deadlineDays);
270|    out.put("waitStage1", isoSeconds(3 * spd));
271|    out.put("waitStage2", isoSeconds(4 * spd));
272|    out.put("waitStage3", isoSeconds(3 * spd));
273|    out.put("waitFinal", isoSeconds(fin));
274|    out.put("callDeadline", isoSeconds((in.deadlineDays + 3L) * spd));
275|    out.put("deadlineAt", Format.rfc3339Utc(deadline.atZone(ZoneId.systemDefault()).toInstant()));
276|    out.put("bridgeTriggered", false);
277|    out.put("bridgeResult", null);
278|    out.put("highRiskLPs", List.of());
279|    out.put("gpDecisions", List.of());
280|    out.put("settlementMode", "normal");
281|    return out;
282|  }
