17|/**
18| * Registers one Camunda job worker per job type.
19| *
20| * <p>Polling and failure handling:
21| *
22| * <ul>
23| *   <li>REST long polling with a 20 s request timeout, up to 16 jobs per type, 60 s job lock;
24| *   <li>200 ms pause after an empty poll, 2 s pause after a failed poll;
25| *   <li>each activated job is handled concurrently (virtual thread per job);
26| *   <li>a handler error fails the job with {@code retries - 1} (never below 0) and a 5 s
27| *       retry back-off, so Camunda raises an incident in Operate once retries are exhausted;
28| *   <li>an unexpected runtime exception is caught and reported as "panic: …", so it shows up
29| *       as an incident instead of killing the worker;
30| *   <li>a successful handler completes the job with the variables it returned.
31| * </ul>
32| */
33|public final class JobWorkers {
34|
35|  /**
36|   * Executes a job and returns the variables to complete it with (may be null). Throwing
37|   * fails the job.
38|   */
39|  @FunctionalInterface
40|  public interface Handler {
41|    Map<String, Object> handle(Job job) throws Exception;
42|  }
43|
44|  /** A handler failure that is expected and already has a usable message. */
45|  public static class JobException extends Exception {
46|    public JobException(String message) {
47|      super(message);
48|    }
49|
50|    public JobException(String message, Throwable cause) {
51|      super(message, cause);
52|    }
53|  }
54|
55|  /** An activated job, wrapped so handlers get typed variable access without touching Jackson. */
56|  public static final class Job {
57|    private final ActivatedJob job;
58|
59|    public Job(ActivatedJob job) {
60|      this.job = job;
61|    }
62|
63|    public long key() {
64|      return job.getKey();
65|    }
66|
67|    public String type() {
68|      return job.getType();
69|    }
70|
71|    public String elementId() {
72|      return job.getElementId();
73|    }
74|
75|    public int retries() {
76|      return job.getRetries();
77|    }
78|
79|    /** Process instance key as a string (the v2 API represents keys as strings). */
80|    public String processInstanceKey() {
81|      return Long.toString(job.getProcessInstanceKey());
82|    }
83|
84|    /** Decodes the job variables into a new value of the given type. */
85|    public <T> T bind(Class<T> type) throws IOException {
86|      String vars = job.getVariables();
87|      if (vars == null || vars.isEmpty()) {
88|        vars = "{}";
89|      }
90|      return JsonCodec.fromJson(vars, type);
91|    }
92|
93|    /** Returns a custom header as string ("" when absent). */
94|    public String header(String name) {
95|      Map<String, String> h = job.getCustomHeaders();
96|      String v = h == null ? null : h.get(name);
97|      return v == null ? "" : v;
98|    }
99|  }
