101|  private final CamundaClient client;
102|  private final String name;
103|  private final Map<String, Handler> handlers = new LinkedHashMap<>();
104|  private final List<JobWorker> open = new ArrayList<>();
105|
106|  /** Number of jobs activated per poll per job type. */
107|  public int maxJobs = 16;
108|  /** How long an activated job is locked to this worker. */
109|  public Duration lockTimeout = Duration.ofSeconds(60);
110|
111|  public JobWorkers(CamundaClient client, String name) {
112|    this.client = client;
113|    this.name = name;
114|  }
115|
116|  public void handle(String jobType, Handler h) {
117|    handlers.put(jobType, h);
