120|  /** Opens one polling job worker per registered job type. */
121|  public synchronized void start() {
122|    for (Map.Entry<String, Handler> e : handlers.entrySet()) {
123|      String jobType = e.getKey();
124|      Handler h = e.getValue();
125|      JobWorker w = client.newWorker()
126|          .jobType(jobType)
127|          .handler((jobClient, job) -> execute(jobClient, job, h))
