153|  void execute(JobClient jobClient, ActivatedJob activated, Handler h) {
154|    Job job = new Job(activated);
155|    Map<String, Object> vars;
156|    try {
157|      vars = h.handle(job);
158|    } catch (Throwable t) {
159|      String msg = errorText(t);
160|      int retries = Math.max(0, job.retries() - 1);
161|      Log.printf("[worker] job %s (%s/%s) failed, retries left %d: %v", Long.toString(job.key()), job.type(),
162|          job.elementId(), retries, msg);
163|      try {
164|        jobClient.newFailCommand(job.key())
165|            .retries(retries)
166|            .errorMessage(msg)
167|            .retryBackoff(Duration.ofSeconds(5))
168|            .send()
169|            .join();
170|      } catch (RuntimeException fe) {
171|        Log.printf("[worker] fail job %s: %v", Long.toString(job.key()), Camunda.message(fe));
172|      }
173|      return;
174|    }
175|    try {
176|      var cmd = jobClient.newCompleteCommand(job.key());
177|      if (vars != null) {
