179|      }
180|      cmd.send().join();
181|    } catch (RuntimeException ce) {
182|      Log.printf("[worker] complete job %s (%s): %v", Long.toString(job.key()), job.type(), Camunda.message(ce));
183|      return;
184|    }
185|    Log.printf("[worker] completed %-22s element=%-28s pi=%s", job.type(), job.elementId(), job.processInstanceKey());
