120|  }
121|
122|  // ─── statement helpers ──────────────────────────────────────────────────
123|
124|  private static final Pattern PLACEHOLDER = Pattern.compile("\\$(\\d+)");
125|
126|  /** Rewrites $n placeholders to ? and binds each argument at every position it appears. */
127|  public static PreparedStatement prepare(Connection c, String sql, Object... args) throws SQLException {
128|    Matcher m = PLACEHOLDER.matcher(sql);
129|    StringBuilder out = new StringBuilder();
130|    List<Integer> order = new ArrayList<>();
131|    while (m.find()) {
132|      order.add(Integer.parseInt(m.group(1)));
133|      m.appendReplacement(out, "?");
134|    }
135|    m.appendTail(out);
136|    PreparedStatement ps = c.prepareStatement(out.toString());
137|    for (int i = 0; i < order.size(); i++) {
138|      bind(c, ps, i + 1, args[order.get(i) - 1]);
139|    }
140|    return ps;
141|  }
142|
143|  private static void bind(Connection c, PreparedStatement ps, int idx, Object v) throws SQLException {
144|    if (v == null) {
145|      ps.setNull(idx, Types.NULL);
146|    } else if (v instanceof Double d) {
147|      if (Double.isFinite(d)) {
148|        // Send NUMERIC as the shortest exact decimal, so a monetary value is not widened
149|        // to a binary-float approximation in the column.
150|        ps.setBigDecimal(idx, new BigDecimal(Double.toString(d)));
151|      } else {
152|        ps.setDouble(idx, d);
153|      }
154|    } else if (v instanceof Integer n) {
155|      ps.setInt(idx, n);
156|    } else if (v instanceof Long n) {
157|      ps.setLong(idx, n);
158|    } else if (v instanceof Boolean b) {
159|      ps.setBoolean(idx, b);
160|    } else if (v instanceof LocalDateTime t) {
161|      ps.setObject(idx, t);
162|    } else if (v instanceof String[] arr) {
163|      Array a = c.createArrayOf("text", arr);
164|      ps.setArray(idx, a);
165|    } else {
166|      ps.setString(idx, v.toString());
167|    }
168|  }
169|
170|  /** pool.Exec / tx.Exec. */
171|  public static int exec(Connection c, String sql, Object... args) throws SQLException {
172|    try (PreparedStatement ps = prepare(c, sql, args)) {
173|      return ps.executeUpdate();
174|    }
175|  }
176|
177|  /** pool.Exec using a pooled connection. */
178|  public int exec(String sql, Object... args) throws SQLException {
179|    try (Connection c = getConnection()) {
180|      return exec(c, sql, args);
181|    }
182|  }
183|
184|  /** Row callback used by {@link #query}. */
185|  @FunctionalInterface
186|  public interface RowReader<T> {
187|    T read(ResultSet rs) throws SQLException;
188|  }
189|
190|  /** pool.Query + rows.Scan. */
191|  public <T> List<T> query(String sql, RowReader<T> reader, Object... args) throws SQLException {
192|    try (Connection c = getConnection(); PreparedStatement ps = prepare(c, sql, args); ResultSet rs = ps.executeQuery()) {
193|      List<T> out = new ArrayList<>();
194|      while (rs.next()) {
195|        out.add(reader.read(rs));
196|      }
197|      return out;
198|    }
199|  }
200|
201|  /**
202|   * Generic query for the dashboard endpoints: every row becomes a map keyed by column name
203|   * (int4→Integer, int8→Long, float8→Double, bool→Boolean, varchar/text→String,
204|   * timestamp→LocalDateTime, NULL→null). Keys are sorted so the JSON field order is stable
205|   * from one response to the next.
206|   */
207|  public List<Map<String, Object>> rowsToMaps(String sql, Object... args) throws SQLException {
208|    try (Connection c = getConnection(); PreparedStatement ps = prepare(c, sql, args); ResultSet rs = ps.executeQuery()) {
209|      ResultSetMetaData md = rs.getMetaData();
210|      List<Map<String, Object>> out = new ArrayList<>();
211|      while (rs.next()) {
212|        Map<String, Object> m = new TreeMap<>();
213|        for (int i = 1; i <= md.getColumnCount(); i++) {
214|          m.put(md.getColumnLabel(i), value(rs, i, md.getColumnTypeName(i)));
215|        }
216|        out.add(m);
217|      }
218|      return out;
219|    }
220|  }
221|
222|  private static Object value(ResultSet rs, int i, String type) throws SQLException {
223|    Object v;
224|    switch (type) {
225|      case "int2", "int4" -> v = rs.getInt(i);
226|      case "int8" -> v = rs.getLong(i);
227|      case "float4", "float8" -> v = rs.getDouble(i);
228|      case "bool" -> v = rs.getBoolean(i);
229|      case "timestamp" -> v = rs.getObject(i, LocalDateTime.class);
230|      case "timestamptz" -> v = rs.getObject(i, java.time.OffsetDateTime.class);
231|      case "numeric" -> v = rs.getBigDecimal(i);
232|      default -> v = rs.getString(i);
233|    }
234|    return rs.wasNull() ? null : v;
235|  }
236|
237|  /** Convenience for building ordered maps in handlers. */
238|  public static Map<String, Object> map() {
239|    return new LinkedHashMap<>();
240|  }
