28|  static String usd(double f) {
29|    String s = Format.fixed(f, 2);
30|    String intPart = s.substring(0, s.length() - 3), dec = s.substring(s.length() - 3);
31|    String neg = "";
32|    if (!intPart.isEmpty() && intPart.charAt(0) == '-') {
33|      neg = "-";
34|      intPart = intPart.substring(1);
35|    }
36|    StringBuilder out = new StringBuilder();
37|    for (int i = 0; i < intPart.length(); i++) {
38|      if (i > 0 && (intPart.length() - i) % 3 == 0) {
39|        out.append(',');
40|      }
41|      out.append(intPart.charAt(i));
42|    }
43|    return neg + "$" + out + dec;
44|  }
