41|        switch (c) {
42|          case '—', '–' -> c = '-';
43|          case '≥' -> c = '>';
44|          default -> c = '?';
45|        }
46|      }
47|      switch (c) {
48|        case '\\' -> b.append("\\\\");
49|        case '(' -> b.append("\\(");
50|        case ')' -> b.append("\\)");
51|        default -> b.appendCodePoint(c);
52|      }
53|    });
54|    return b.toString();
55|  }
