82|    Out out = new Out();
83|    out.raw("%PDF-1.4\n");
84|    out.bytes(new byte[] {'%', (byte) 0xe2, (byte) 0xe3, (byte) 0xcf, (byte) 0xd3, '\n'});
85|    int n = pages.size();
86|    // 1 catalog, 2 pages, 3-5 fonts, then per page: page obj + content obj
87|    out.obj("<< /Type /Catalog /Pages 2 0 R >>");
88|    List<String> kids = new ArrayList<>();
89|    for (int i = 0; i < n; i++) {
90|      kids.add(sprintf("%d 0 R", 6 + i * 2));
91|    }
92|    out.obj(sprintf("<< /Type /Pages /Kids [%s] /Count %d >>", String.join(" ", kids), n));
93|    out.obj("<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>");
94|    out.obj("<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>");
95|    out.obj("<< /Type /Font /Subtype /Type1 /BaseFont /Courier /Encoding /WinAnsiEncoding >>");
96|    for (int i = 0; i < n; i++) {
97|      String content = pages.get(i);
98|      out.obj(sprintf("<< /Type /Page /Parent 2 0 R /MediaBox [0 0 %.0f %.0f] /Resources << /Font << /F1 3 0 R /F2 4 0 R /F3 5 0 R >> >> /Contents %d 0 R >>",
99|          pageW, pageH, 7 + i * 2));
100|      out.obj(sprintf("<< /Length %d >>\nstream\n%sendstream", content.getBytes(StandardCharsets.UTF_8).length, content));
101|    }
102|    int xref = out.size();
103|    out.raw(sprintf("xref\n0 %d\n0000000000 65535 f \n", out.offsets.size() + 1));
104|    for (int o : out.offsets) {
105|      out.raw(sprintf("%010d 00000 n \n", o));
106|    }
107|    out.raw(sprintf("trailer\n<< /Size %d /Root 1 0 R >>\nstartxref\n%d\n%%%%EOF\n", out.offsets.size() + 1, xref));
108|    return out.toByteArray();
109|  }
110|
111|  private static String footer(double marginL, int pageNo) {
112|    return sprintf("BT /F1 8 Tf %.1f %.1f Td (Page %d - Intelligent Capital Call & Liquidity Orchestration - Camunda 8) Tj ET\n",
113|        marginL, 30.0, pageNo);
114|  }
115|
116|  private static final class Out {
117|    final ByteArrayOutputStream buf = new ByteArrayOutputStream();
118|    final List<Integer> offsets = new ArrayList<>();
119|
120|    void raw(String s) {
121|      bytes(s.getBytes(StandardCharsets.UTF_8));
122|    }
123|
124|    void bytes(byte[] b) {
125|      buf.writeBytes(b);
126|    }
127|
128|    int size() {
129|      return buf.size();
130|    }
131|
132|    void obj(String body) {
133|      offsets.add(buf.size());
134|      raw(sprintf("%d 0 obj\n%s\nendobj\n", offsets.size(), body));
135|    }
136|
137|    byte[] toByteArray() {
138|      return buf.toByteArray();
139|    }
140|  }
