  /** Message forceSettlement: closes the response window early. */
  @SignalMethod(name = "forceSettlement")
  void forceSettlement();

  /** Message cancelCall: cancels the call. */
  @SignalMethod(name = "cancelCall")
  void cancelCall();
}
